contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool callerIsOwner, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Seed c with some Ether so withdrawal is meaningful.
        (bool sent) = address(c).send(amount);
        require(sent);

        uint256 cBalBefore = address(c).balance;
        if (!callerIsOwner) {
            // Since msg.sender is this contract and c.Owner() is the deployer (this contract),
            // the 'false' branch is unreachable in normal deployment; but keep it structural.
            // We only assert in the true branch below.
        }

        // The deciding call: only owner can withdraw.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // After a successful withdrawal, c's balance is zero, and the owner received
            // exactly the entire pre-call balance. Since owner == this contract, we can
            // observe the Ether received by this contract (excluding the initial seed).
            assert(address(c).balance == 0);
        } else {
            // If it reverted, c's balance is unchanged.
            assert(address(c).balance == cBalBefore);
        }
    }

    receive() external payable {}
}

