contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        // Only the owner can call withdraw successfully; non-owner calls must revert.
        // We test both cases using the fact that the test contract is the owner.
        require(caller == address(this) || caller != c.Owner(), "invalid caller");
        // Ensure the test contract has enough Ether to fund the contract if needed.
        require(address(this).balance >= msg.value, "insufficient balance");

        // Setup: fund c with some Ether via its receive function.
        (bool sent, ) = address(c).call{value: msg.value}("");
        require(sent, "funding failed");

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        if (caller == c.Owner()) {
            // Owner calls withdraw: should succeed and transfer entire balance to owner.
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner calls withdraw: must revert.
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule: If the caller is the owner, withdraw must not revert and must drain the entire balance.
        // If the caller is not the owner, withdraw must revert and leave the balance unchanged.
        if (caller == c.Owner()) {
            assert(!reverted && afterBalance == 0);
        } else {
            assert(reverted && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

